/**
 * Script Manager — file-based Python script lifecycle management.
 *
 * Manages saving, reading, patching, and tracking repair attempts
 * for Python scripts generated by Claude. Scripts are stored on disk
 * under a session-scoped temp directory.
 */

import fs from 'fs';
import path from 'path';
import os from 'os';
import { applyUnifiedDiff, type PatchResult } from './diffEngine';
import {
  parseExecutionOutput,
  formatErrorsForClaude,
  type StructuredLogResult,
} from './structuredLogger';

// ── Types ──────────────────────────────────────────────────────────

export interface ScriptMeta {
  scriptId: string;
  filePath: string;
  createdAt: number;
  repairAttempts: number;
  patchedLines: Set<number>;  // lines previously corrected (guard against re-patching)
  lastError: StructuredLogResult | null;
}

export interface RunPythonResult {
  success: boolean;
  output?: string;
  result?: any;
  figures?: string[];
  files?: Array<{ filename: string; filepath: string }>;
  error?: string;
  structuredErrors?: string;  // JSON string of StructuredLogResult
  scriptId?: string;
  scriptPath?: string;
}

// ── Constants ──────────────────────────────────────────────────────

const MAX_REPAIR_ATTEMPTS = 8;
const SCRIPTS_BASE_DIR = path.join(os.tmpdir(), 'autoscholar-scripts');

// ── In-memory registry ─────────────────────────────────────────────

/** scriptId → ScriptMeta */
const scriptRegistry = new Map<string, ScriptMeta>();

// ── Helpers ────────────────────────────────────────────────────────

function ensureDir(dir: string): void {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function generateScriptId(): string {
  return `script-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;
}

// ── Public API ─────────────────────────────────────────────────────

/**
 * Save a new Python script to disk and register it.
 */
export function saveScript(code: string, sessionId?: string): ScriptMeta {
  const scriptId = generateScriptId();
  const sessionDir = path.join(SCRIPTS_BASE_DIR, sessionId || 'default');
  ensureDir(sessionDir);

  const filePath = path.join(sessionDir, `${scriptId}.py`);
  fs.writeFileSync(filePath, code, 'utf-8');

  const meta: ScriptMeta = {
    scriptId,
    filePath,
    createdAt: Date.now(),
    repairAttempts: 0,
    patchedLines: new Set(),
    lastError: null,
  };

  scriptRegistry.set(scriptId, meta);
  return meta;
}

/**
 * Read a script's content from disk.
 */
export function readScript(scriptId: string): { success: boolean; content?: string; error?: string } {
  const meta = scriptRegistry.get(scriptId);
  if (!meta) {
    return { success: false, error: `Script "${scriptId}" not found in registry.` };
  }

  if (!fs.existsSync(meta.filePath)) {
    return { success: false, error: `Script file not found on disk: ${meta.filePath}` };
  }

  const content = fs.readFileSync(meta.filePath, 'utf-8');
  return { success: true, content };
}

/**
 * Apply a unified diff patch to an existing script.
 * Enforces the MAX_REPAIR_ATTEMPTS limit and tracks patched lines.
 */
export function patchScript(
  scriptId: string,
  diff: string,
): PatchResult & { repairAttempt: number; maxReached: boolean } {
  const meta = scriptRegistry.get(scriptId);
  if (!meta) {
    return {
      success: false,
      patched: '',
      hunksApplied: 0,
      hunksTotal: 0,
      error: `Script "${scriptId}" not found in registry.`,
      repairAttempt: 0,
      maxReached: false,
    };
  }

  if (meta.repairAttempts >= MAX_REPAIR_ATTEMPTS) {
    return {
      success: false,
      patched: '',
      hunksApplied: 0,
      hunksTotal: 0,
      error: `Maximum repair attempts (${MAX_REPAIR_ATTEMPTS}) reached for script "${scriptId}". Full rewrite required.`,
      repairAttempt: meta.repairAttempts,
      maxReached: true,
    };
  }

  const readResult = readScript(scriptId);
  if (!readResult.success || !readResult.content) {
    return {
      success: false,
      patched: '',
      hunksApplied: 0,
      hunksTotal: 0,
      error: readResult.error || 'Failed to read script.',
      repairAttempt: meta.repairAttempts,
      maxReached: false,
    };
  }

  const patchResult = applyUnifiedDiff(readResult.content, diff);

  if (patchResult.success) {
    // Write patched content back to disk
    fs.writeFileSync(meta.filePath, patchResult.patched, 'utf-8');
    meta.repairAttempts++;

    // Track which lines were modified (approximate from hunk headers)
    const hunkHeaderRe = /^@@\s+-(\d+)(?:,(\d+))?\s+/gm;
    let match;
    while ((match = hunkHeaderRe.exec(diff)) !== null) {
      const start = parseInt(match[1], 10);
      const count = match[2] !== undefined ? parseInt(match[2], 10) : 1;
      for (let l = start; l < start + count; l++) {
        meta.patchedLines.add(l);
      }
    }
  }

  return {
    ...patchResult,
    repairAttempt: meta.repairAttempts,
    maxReached: meta.repairAttempts >= MAX_REPAIR_ATTEMPTS,
  };
}

/**
 * Get the file path for a registered script.
 */
export function getScriptPath(scriptId: string): string | null {
  return scriptRegistry.get(scriptId)?.filePath || null;
}

/**
 * Get metadata for a script.
 */
export function getScriptMeta(scriptId: string): ScriptMeta | null {
  return scriptRegistry.get(scriptId) || null;
}

/**
 * Store the latest execution error for a script.
 */
export function setLastError(scriptId: string, stdout: string, stderr: string): StructuredLogResult | null {
  const meta = scriptRegistry.get(scriptId);
  if (!meta) return null;

  const parsed = parseExecutionOutput(stdout, stderr);
  meta.lastError = parsed;
  return parsed;
}

/**
 * Get the last structured error for a script (for inspect_logs).
 */
export function getLastError(scriptId: string): string | null {
  const meta = scriptRegistry.get(scriptId);
  if (!meta || !meta.lastError) return null;
  return formatErrorsForClaude(meta.lastError);
}

/**
 * Get repair attempt info for a script.
 */
export function getRepairInfo(scriptId: string): {
  repairAttempts: number;
  maxRepairs: number;
  patchedLines: number[];
} | null {
  const meta = scriptRegistry.get(scriptId);
  if (!meta) return null;

  return {
    repairAttempts: meta.repairAttempts,
    maxRepairs: MAX_REPAIR_ATTEMPTS,
    patchedLines: Array.from(meta.patchedLines).sort((a, b) => a - b),
  };
}

/**
 * Clean up scripts for a session.
 */
export function cleanupSession(sessionId: string): void {
  const sessionDir = path.join(SCRIPTS_BASE_DIR, sessionId || 'default');

  // Remove registry entries for this session
  const entries = Array.from(scriptRegistry.entries());
  for (const [id, meta] of entries) {
    if (meta.filePath.startsWith(sessionDir)) {
      scriptRegistry.delete(id);
    }
  }

  // Remove files
  if (fs.existsSync(sessionDir)) {
    try {
      fs.rmSync(sessionDir, { recursive: true, force: true });
    } catch {
      // best-effort cleanup
    }
  }
}

/**
 * Clean up all scripts older than a given age (in ms).
 */
export function cleanupStale(maxAgeMs: number = 3600_000): void {
  const now = Date.now();

  const staleEntries = Array.from(scriptRegistry.entries());
  for (const [id, meta] of staleEntries) {
    if (now - meta.createdAt > maxAgeMs) {
      try {
        if (fs.existsSync(meta.filePath)) {
          fs.unlinkSync(meta.filePath);
        }
      } catch {
        // ignore
      }
      scriptRegistry.delete(id);
    }
  }
}
